    p = d / "metrics_v2.json"
    if not p.exists():
        p = d / "metrics.json"
    if not p.exists():
        return None
    with open(p) as f:
        m = json.load(f)
    if m.get("field_compliance_rate", 0) == 0 or m.get("f1", 0) < 0.01:
        return None
    m["_source_dir"] = eval_dir_name
    m["_source_file"] = p.name
    if p.name == "metrics.json":
        m.pop("ign_f1", None)
    return m


def mean(vals):
    return sum(vals) / len(vals) if vals else float("nan")

def std(vals):
    if len(vals) < 2:
        return float("nan")
    m = mean(vals)
    return math.sqrt(sum((v - m) ** 2 for v in vals) / (len(vals) - 1))

def cohens_d(a, b):
    if len(a) < 2 or len(b) < 2:
        return float("nan")
    diffs = [x - y for x, y in zip(a, b)]
    d_mean, d_std = mean(diffs), std(diffs)
    if d_std == 0:
        return float("inf") if d_mean != 0 else 0.0
    return d_mean / d_std

def paired_ttest(a, b):
    n = len(a)
    if n < 2:
        return float("nan"), float("nan"), n
    diffs = [x - y for x, y in zip(a, b)]
    d_mean, d_std = mean(diffs), std(diffs)
    if d_std == 0:
        return (float("inf") if d_mean != 0 else 0.0), 0.0, n
    t_stat = d_mean / (d_std / math.sqrt(n))
    try:
        from scipy import stats as sp_stats
        p_val = sp_stats.t.sf(abs(t_stat), df=n - 1) * 2
    except ImportError:
        p_val = None
    return t_stat, p_val, n

def ci_95(vals):
    n = len(vals)
    if n < 2:
        return (float("nan"), float("nan"))
    m, s = mean(vals), std(vals)
    t_crit_map = {2: 12.706, 3: 4.303, 4: 3.182, 5: 2.776}
    t_crit = t_crit_map.get(n, 2.0)
    margin = t_crit * s / math.sqrt(n)
    return (m - margin, m + margin)


def build_comparison():
    seeds = ["s42", "s43", "s44", "s45"]
    data = {}
    sources = {}
    for method, seed_dirs in METHODS.items():
        data[method] = {}
        sources[method] = {}
        for seed in seeds:
            dir_name = seed_dirs.get(seed)
            if dir_name is None:
                continue
            m = load_metrics(dir_name)
            if m is not None:
                sources[method][seed] = {"dir": m.pop("_source_dir"), "file": m.pop("_source_file")}
                data[method][seed] = {k: m[k] for k in METRICS_KEYS if k in m}
    return data, seeds, sources


def fv(v, fmt=".4f"):
    if v is None or (isinstance(v, float) and math.isnan(v)):
        return "—"
    return f"{v:{fmt}}"


def generate_report(data, seeds, sources):
    lines = []
    lines.append("# flat-NLI vs CED RSFT: Seed-Level Comparison (Unified Protocol)")
    lines.append(f"Generated: {datetime.now().strftime('%Y-%m-%d %H:%M:%S')}")
    lines.append("")

    ced_ready = list(data.get("CED_RSFT", {}).keys())
    fnli_ready = list(data.get("flatNLI_RSFT", {}).keys())
    lines.append(f"**CED RSFT**: {len(ced_ready)}/{len(seeds)} seeds ({', '.join(ced_ready)})")
    lines.append(f"**flat-NLI RSFT**: {len(fnli_ready)}/{len(seeds)} seeds ({', '.join(fnli_ready)})")
    missing_ced = [s for s in seeds if s not in ced_ready]
    missing_fnli = [s for s in seeds if s not in fnli_ready]
    if missing_ced:
        lines.append(f"**Pending CED**: {', '.join(missing_ced)}")
    if missing_fnli:
        lines.append(f"**Pending flat-NLI**: {', '.join(missing_fnli)}")
    lines.append("")

    # Source directories
    lines.append("## Data Sources")
    for method in ["CED_RSFT", "flatNLI_RSFT"]:
        for seed in seeds:
            if seed in sources.get(method, {}):
                src = sources[method][seed]
                lines.append(f"- {method} {seed}: `{src['dir']}/` ({src['file']})")
    lines.append("")

    # Per-seed table
    lines.append("## Per-Seed Results")
    lines.append("")
    lines.append("| Seed | CED Ign-F1 | fNLI Ign-F1 | CED rel_f1 | fNLI rel_f1 | CED evi_f1 | fNLI evi_f1 | CED EDCR | fNLI EDCR |")
    lines.append("|------|-----------|------------|-----------|------------|-----------|------------|---------|----------|")
    for seed in seeds:
        ced = data.get("CED_RSFT", {}).get(seed, {})
        fnli = data.get("flatNLI_RSFT", {}).get(seed, {})
        lines.append(f"| {seed} | {fv(ced.get('ign_f1'))} | {fv(fnli.get('ign_f1'))} | {fv(ced.get('f1'))} | {fv(fnli.get('f1'))} | {fv(ced.get('evi_f1'))} | {fv(fnli.get('evi_f1'))} | {fv(ced.get('edcr'))} | {fv(fnli.get('edcr'))} |")
    lines.append("")

    # Summary stats
    lines.append("## Summary Statistics")
    lines.append("")
    json_out = {"per_seed": {}, "summary": {}, "sources": sources}

    for mk, label in METRIC_LABELS.items():
        ced_vals = [data["CED_RSFT"][s][mk] for s in seeds if s in data.get("CED_RSFT", {}) and mk in data["CED_RSFT"].get(s, {})]
        fnli_vals = [data["flatNLI_RSFT"][s][mk] for s in seeds if s in data.get("flatNLI_RSFT", {}) and mk in data["flatNLI_RSFT"].get(s, {})]
        ced_m, ced_s = mean(ced_vals), std(ced_vals)
        fnli_m, fnli_s = mean(fnli_vals), std(fnli_vals)
        delta = fnli_m - ced_m if not (math.isnan(fnli_m) or math.isnan(ced_m)) else float("nan")

        lines.append(f"**{label}**:")
        lines.append(f"  - CED:  {fv(ced_m)} +/- {fv(ced_s)} (n={len(ced_vals)})")
        lines.append(f"  - fNLI: {fv(fnli_m)} +/- {fv(fnli_s)} (n={len(fnli_vals)})")
        lines.append(f"  - Delta (fNLI - CED): {fv(delta, '+.4f')}")

        matched = [s for s in seeds if s in data.get("CED_RSFT", {}) and s in data.get("flatNLI_RSFT", {}) and mk in data["CED_RSFT"].get(s, {}) and mk in data["flatNLI_RSFT"].get(s, {})]
        stat_info = {}
        if len(matched) >= 2:
            a = [data["CED_RSFT"][s][mk] for s in matched]
            b = [data["flatNLI_RSFT"][s][mk] for s in matched]
            t_stat, p_val, n = paired_ttest(a, b)
            d = cohens_d(b, a)
            ci_lo, ci_hi = ci_95([bv - av for av, bv in zip(a, b)])
            p_str = "N/A (no scipy)" if p_val is None else fv(p_val, ".4f")
            lines.append(f"  - Paired t-test: t={fv(t_stat, '.3f')}, p={p_str}, n={n}")
            lines.append(f"  - Cohen's d: {fv(d, '.3f')}")
            lines.append(f"  - 95% CI (Delta): [{fv(ci_lo, '.4f')}, {fv(ci_hi, '.4f')}]")
            if n < 4:
                lines.append(f"  - WARNING: N={n} < 4, waiting for more seeds")
            stat_info = {"t_stat": t_stat, "p_value": p_val, "cohens_d": d, "ci_95": [ci_lo, ci_hi], "n_paired": n}
        else:
            lines.append(f"  - WARNING: {len(matched)} matched seed(s), need >=2 for paired stats")
        lines.append("")

        json_out["summary"][label] = {
            "CED_mean": ced_m, "CED_std": ced_s, "CED_n": len(ced_vals),
            "fNLI_mean": fnli_m, "fNLI_std": fnli_s, "fNLI_n": len(fnli_vals),
            "delta": delta, **stat_info,
        }

    for seed in seeds:
        json_out["per_seed"][seed] = {}
        for method in ["CED_RSFT", "flatNLI_RSFT"]:
            if seed in data.get(method, {}):
                json_out["per_seed"][seed][method] = {METRIC_LABELS[k]: v for k, v in data[method][seed].items() if k in METRICS_KEYS}

    json_out["status"] = {
        "CED_seeds_ready": ced_ready,
        "flatNLI_seeds_ready": fnli_ready,
        "missing_CED": missing_ced,
        "missing_flatNLI": missing_fnli,
        "all_complete": len(ced_ready) == 4 and len(fnli_ready) == 4,
    }
    return "\n".join(lines), json_out


def run_once():
    data, seeds, sources = build_comparison()
    md, js = generate_report(data, seeds, sources)
    (OUT_DIR / "seed_comparison.md").write_text(md)
    (OUT_DIR / "seed_comparison.json").write_text(json.dumps(js, indent=2, ensure_ascii=False, cls=NanSafeEncoder))
    return md, js


def main():
    parser = argparse.ArgumentParser()
    parser.add_argument("--watch", type=int, default=0, help="Watch interval in seconds")
    parser.add_argument("--json-only", action="store_true")
    parser.add_argument("--dry-run", action="store_true", help="Print what would be loaded without writing files")
    args = parser.parse_args()

    if args.dry_run:
        seeds = ["s42", "s43", "s44", "s45"]
        for method, seed_dirs in METHODS.items():
            print(f"\n=== {method} ===")
            for seed in seeds:
                dir_name = seed_dirs.get(seed)
                if dir_name is None:
                    print(f"  {seed}: NOT CONFIGURED")
                    continue
                m = load_metrics(dir_name)
                if m is not None:
                    src_dir = m.get("_source_dir", "?")
                    src_file = m.get("_source_file", "?")
                    ign_f1 = m.get("ign_f1")
                    ign_str = f", ign_f1={ign_f1:.4f}" if ign_f1 is not None else ", ign_f1=N/A"
                    print(f"  {seed}: LOADED from {src_dir}/{src_file}  (f1={m.get('f1', 0):.4f}{ign_str})")
                else:
                    candidates = dir_name if isinstance(dir_name, list) else [dir_name]
                    print(f"  {seed}: NOT FOUND (tried: {', '.join(candidates)})")
        return

    if args.watch > 0:
        print(f"[watch] Checking every {args.watch}s. Ctrl+C to stop.")
        prev_n = 0
        while True:
            md, js = run_once()
            cur_ced = len(js["status"]["CED_seeds_ready"])
            cur_fnli = len(js["status"]["flatNLI_seeds_ready"])
            cur_n = cur_ced + cur_fnli
            if cur_n != prev_n:
                print("\n" + "=" * 60)
                print(md if not args.json_only else json.dumps(js, indent=2, cls=NanSafeEncoder))
                prev_n = cur_n
                if js["status"]["all_complete"]:
                    print("\nAll 8 seeds complete (4 CED + 4 flat-NLI)!")
                    break
            else:
                print(f"[{datetime.now().strftime('%H:%M:%S')}] CED {cur_ced}/4, fNLI {cur_fnli}/4 seeds ready.")
            time.sleep(args.watch)
    else:
        md, js = run_once()
        print(md if not args.json_only else json.dumps(js, indent=2, cls=NanSafeEncoder))
        print(f"\nWritten: {OUT_DIR}/seed_comparison.{{md,json}}")

if __name__ == "__main__":
    main()
